{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "5-hydroxyrofecoxib, a polar methylsulfonylphenyl-substituted heterocycle, had an absolute oral bioavailability of only 14.9% in healthy subjects after a 10 mg oral dose versus i.v., providing direct human evidence that a strongly polar sulfonyl-containing molecule can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Edaravone, which shares the 1-phenyl-3-methylpyrazolone core with the query but lacks the sulfonic acid side chain, had an absolute oral bioavailability of 57.3% in healthy subjects, indicating that the core scaffold is not inherently poorly bioavailable and that the acid group is the key liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query contains a strongly acidic sulfonic acid group that is anionic at physiological pH, giving very low logD and high polar surface area, which predicts poor intestinal permeability. The most relevant experimental anchor, 5-hydroxyrofecoxib, a polar sulfonyl-containing heterocycle, had human oral bioavailability near 15%, below the 20% threshold. High-F analogues such as edaravone share the pyrazolone core but lack the acid, confirming the scaffold is not the barrier. Therefore low oral bioavailability is the better-supported prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query or a close sulfonic-acid analogue; the closest low-F analogue has a methylsulfonyl rather than sulfonic acid group.",
    "Transporter-mediated absorption or active uptake was not assessed; a strong acid might still be absorbed via carriers, but no evidence supports this.",
    "Metabolic stability and first-pass extraction are unknown; if the acid prevents absorption, F will be low, but if it is a prodrug or substrate of uptake transporters, F could be higher."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

